def octicon(name: str, *, size: int = 16, label: str = "", cls: str = "") -> SafeHTML:
    """Return an inline SVG Octicon; decorative unless *label* is given."""
    body = _PATHS[name]
    extra = f" {cls}" if cls else ""
    if label:
        a11y = f'role="img" aria-label="{escape(label, quote=True)}"'
    else:
        a11y = 'aria-hidden="true"'
    return safe_html(
        f'<svg class="octicon octicon-{name}{extra}" viewBox="0 0 16 16" width="{size}" height="{size}" fill="currentColor" {a11y}>{body}</svg>'
    )
